"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[4517],{8751(e){e.exports=JSON.parse('{"title":"\uc2e4\uc6a9\uc801\uc778 \ud504\ub808\uc784\uc6cc\ud06c \uc0ac\uc6a9 \uac00\uc774\ub4dc","date":"2025-07-23","coverUrl":"/kudzu-based-bench/assets/notion/7f480d976e3a7bc2.png","html":"<h1 data-notion-block-id=\\"232e548d-8a8e-80f9-bead-ca58456b191d\\">Beyond the Article: \ud55c \uac78\uc74c \ub354</h1><h2 data-notion-block-id=\\"235e548d-8a8e-8023-a626-cfe4f3a8e6d4\\" id=\\"235e548d-8a8e-8023-a626-cfe4f3a8e6d4\\">\uc2e4\uc6a9\uc801\uc778 \ud504\ub808\uc784\uc6cc\ud06c \uc0ac\uc6a9 \uac00\uc774\ub4dc</h2><a href=\\"https://www.lorenstew.art/blog/always-architect-with-contraints\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.lorenstew.art/blog/always-architect-with-contraints</a><p data-notion-block-id=\\"235e548d-8a8e-8046-827d-c1ebf2063d86\\">\ubb34\uc870\uac74 \uc775\uc219\ud55c \ud504\ub808\uc784\uc6cc\ud06c\ub97c \uc0ac\uc6a9\ud558\uae30\ubcf4\ub2e4, \uc790\uc2e0\uc774 \uad6c\ud604\ud558\ub824\ub294 \uc81c\uc57d\uc870\uac74\uc774 \ubb34\uc5c7\uc778\uc9c0 \uae68\ub2eb\uace0 \ud504\ub808\uc784\uc6cc\ud06c\ub97c \uc120\ud0dd\ud558\ub294 \uac83\uc774 \uc88b\uc740 \uc544\ud0a4\ud14d\uccd0\ub85c \ub098\uc544\uac00\ub294 \ubc29\ubc95\uc774\ub77c\uace0 \uc81c\uc548\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ubaa8\ub4e0 \ud504\ub808\uc784\uc6cc\ud06c\ub97c \uadf8\ub300\ub85c \ub530\ub974\ub294 \uac83\ubcf4\ub2e4\ub294 \ud504\ub808\uc784\uc6cc\ud06c\ub97c \ube44\ud310\uc801\uc73c\ub85c \uc0dd\uac01\ud558\uace0 \uc120\ud0dd\ud558\ub77c\ub294 \uac83\uc774\uc8e0. \ubb3c\ub860 \uc81c\uc57d\uc0ac\ud56d\uc5d0 <a href=\\"https://ones-to-watch.ethansup.net/news/post/16be548d-8a8e-8042-ae4b-ff077a1a1d1f#16be548d-8a8e-80b6-b42c-c841f50ccd04\\">\uc778\uc9c0\ubd80\ud558</a>\uac00 \uc788\uc744 \uc218 \uc788\uc73c\ubbc0\ub85c, \uc0ac\uc6a9\uc790\uc5d0\uac8c \uc88b\uc6b4 \ud504\ub808\uc784\uc6cc\ud06c\ub97c \uc120\ud0dd\ud558\ub294 \uac83\ub9cc\uc774 \uc88b\uc740 \uae38\uc774 \uc544\ub2d0 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \ubaa8\ub4e0 \uac83\uc740 \uc81c\uc57d\uc0ac\ud56d\uc774 \uc5b4\ub5a4\uc9c0\uc5d0 \ub530\ub77c \ub2ec\ub824\uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"235e548d-8a8e-80c4-98ba-f1850c700ba1\\" id=\\"235e548d-8a8e-80c4-98ba-f1850c700ba1\\">\ub9c8\uc774\uadf8\ub808\uc774\uc158\uc740 \uc5b8\uc81c\ub098 \ud798\ub4e4\ub2e4.</h2><a href=\\"https://craft.faire.com/the-worlds-longest-react-hooks-migration-8f357cdcdbe9\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://craft.faire.com/the-worlds-longest-react-hooks-migration-8f357cdcdbe9</a><p data-notion-block-id=\\"235e548d-8a8e-8076-838b-d783b6397df1\\">2022\ub144\ubd80\ud130 \uc9c0\uae08\uae4c\uc9c0, MobX\uc640 \ud074\ub798\uc2a4 \ucef4\ud3ec\ub10c\ud2b8\uac00 \uc5b4\ub5a4 \ubb38\uc81c\ub97c \uac16\uace0 \uc788\uc5c8\ub294\uc9c0, \uadf8\ub9ac\uace0 \uc5b4\ub5a4 \ub9c8\uc774\uadf8\ub808\uc774\uc158 \uc804\ub7b5\uc744 \uc9f0\ub294\uc9c0, \uc5b4\ub5a4 \uac83\uc774 \ubcd1\ubaa9\uc774 \ub418\uc5c8\ub294\uc9c0\uae4c\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uacb0\uad6d, \uc870\uc9c1\uc801\uc73c\ub85c \uacf5\ud1b5\ub41c \ubbff\uc74c\uacfc \uc124\ub4dd\uc774 \ud544\uc694\ud568\uc744 \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"232e548d-8a8e-8065-80bf-e6b08333801c\\">Straight to the Article: \ube5b\ub098\ub294 \uc778\uc0ac\uc774\ud2b8</h1><h2 data-notion-block-id=\\"235e548d-8a8e-8059-8af8-debe5d7d567d\\" id=\\"235e548d-8a8e-8059-8af8-debe5d7d567d\\">nvm\uc744 \uc0ac\uc6a9\ud558\uc9c0 \uc54a\ub294 \uac83\uc740 \uc758\uc678\ub85c \uac1c\ubc1c\uc5d0 \ub3c4\uc6c0\uc774 \ub41c\ub2e4</h2><a href=\\"https://nodevibe.substack.com/p/the-500x-performance-gap-between\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nodevibe.substack.com/p/the-500x-performance-gap-between</a><p data-notion-block-id=\\"235e548d-8a8e-80f6-89ba-caa7dd329cae\\">shell\uc5d0\uc11c warm start\uc640 cold start\uac00 \uc5b4\ub5bb\uac8c \uc791\ub3d9\ud558\ub294\uc9c0, \uadf8\ub9ac\uace0 nvm\uacfc fnm/volta\ub294 \uc5b4\ub5bb\uac8c \ub2e4\ub978\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uadf8\ub9ac\uace0 nvm \ub300\uc2e0 fnm/volta\ub97c \uc0ac\uc6a9\ud558\uba74 \uc5bc\ub9c8\ub098 \uac1c\ubc1c \uc2dc\uac04\uc744 \uc544\ub084 \uc218 \uc788\ub294\uc9c0 \ubca4\uce58\ub9c8\ud06c\ub85c \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"235e548d-8a8e-80a1-a027-e6c9e1626eb0\\" id=\\"235e548d-8a8e-80a1-a027-e6c9e1626eb0\\"><code>Promise.all</code>, \uc798 \uc4f0\uae30 \uc704\ud55c \ud0c0\uc785\uacfc \ud568\uc218</h2><a href=\\"https://spin.atomicobject.com/better-promise-all/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://spin.atomicobject.com/better-promise-all/</a><p data-notion-block-id=\\"235e548d-8a8e-80fd-97ae-d0a1a488e496\\"><code>Promise.all</code>(<code>Promise.allSettled</code>)\uc744 \ub354 \uc798 \uc4f0\uae30 \uc704\ud574 utility type\uacfc function\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"232e548d-8a8e-80ec-8d78-f81601882db0\\" id=\\"232e548d-8a8e-80ec-8d78-f81601882db0\\">WASM\uc740 \uc5b4\ub514\uc5d0 \uc4f0\ub294\uac70\uc8e0?</h2><a href=\\"https://queue.acm.org/detail.cfm?id=3746171\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://queue.acm.org/detail.cfm?id=3746171</a><p data-notion-block-id=\\"235e548d-8a8e-8010-8efa-f6c203f83fa1\\">WASM\uc5d0 \ub300\ud55c \uac04\ub2e8\ud55c \uc774\ud574\uc640 WASM\uc758 \uc6f9, \uc6f9\uc774 \uc544\ub2cc \uacf3\uc5d0\uc11c\uc758 \uc131\uacf5\uc0ac\ub840\ub97c \uc0b4\ud3b4\ubcf4\uba74\uc11c, \ud604\uc7ac \uac01 \ubd84\uc57c\uc5d0\uc11c\uc758 WASM\uc774 \uc5b4\ub5a4 \uc0c1\ud669\uc5d0 \uc788\uace0, \uc5b4\ub5a4 \ubbf8\ub798\ub85c \ud758\ub7ec\uac08 \uac83\uc778\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"235e548d-8a8e-80ee-9c01-cb1709972944\\" id=\\"235e548d-8a8e-80ee-9c01-cb1709972944\\">\ucffc\ub9ac\ube4c\ub354 \ube44\uad50\ud558\uae30</h2><a href=\\"https://marmelab.com/blog/2025/06/26/kysely-vs-drizzle.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://marmelab.com/blog/2025/06/26/kysely-vs-drizzle.html</a><p data-notion-block-id=\\"232e548d-8a8e-80d2-81c6-f40b31c1fc59\\">Typescript \uae30\ubc18 \ucffc\ub9ac \ube4c\ub354 \ub450 \uac00\uc9c0(Kysely, Drizzle)\ub97c \ube44\uad50\ud574\uac00\uba74\uc11c \uc5b4\ub5a4 \uac83\uc774 \uc5b4\ub5a4 \uce21\uba74\uc5d0\uc11c \uc88b\uc740\uc9c0 \ube44\uad50\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"232e548d-8a8e-8058-b934-f4ca0c39f9e9\\" id=\\"232e548d-8a8e-8058-b934-f4ca0c39f9e9\\">Module Federation \uc54c\uc544\ubcf4\uae30</h2><a href=\\"https://developersvoice.com/blog/frontend/micro-frontends-with-react-and-angular/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://developersvoice.com/blog/frontend/micro-frontends-with-react-and-angular/</a><p data-notion-block-id=\\"235e548d-8a8e-80d5-b8f5-d434855726e2\\">Micro frontend\ub97c \uc120\ud0dd\ud560 \ub54c Module Federation\uc774 \uc65c \uc88b\uc740 \uc120\ud0dd\uc9c0\uc778\uc9c0, \uadf8\ub9ac\uace0 \uc2e4\uc81c \uc0c1\ud669\uc5d0\uc11c\ub294 \uc5b4\ub5bb\uac8c \ud574\uc57c\ud558\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"235e548d-8a8e-8017-b46f-e6a67654307f\\" id=\\"235e548d-8a8e-8017-b46f-e6a67654307f\\">tabindex \uc798 \uc0ac\uc6a9\ud558\ub294 \ubc29\ubc95</h2><a href=\\"https://blog.pope.tech/2025/07/01/tabindex-what-it-is-how-it-works-and-when-to-use-it/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.pope.tech/2025/07/01/tabindex-what-it-is-how-it-works-and-when-to-use-it/</a><h1 data-notion-block-id=\\"232e548d-8a8e-80af-b3bb-ee54559306ee\\">Fresh Finds: \ub193\uce58\uc9c0 \ub9d0\uc544\uc57c \ud560 \uc18c\uc2dd</h1><a href=\\"https://nextjs.org/blog/next-15-4\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nextjs.org/blog/next-15-4</a><p data-notion-block-id=\\"232e548d-8a8e-806f-adb8-f9769dbfb039\\">\uc548\uc815\uc131\uc744 \uc704\ud55c Next.js 15.4 \uc18c\uc2dd\uc774 Next.js 16\uc774 \uc5b4\ub5bb\uac8c \ub420\uc9c0\uc5d0 \ub300\ud55c \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://nuxt.com/blog/v4\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nuxt.com/blog/v4</a><p data-notion-block-id=\\"235e548d-8a8e-80cd-b9bd-dc315b3414cf\\">\uc0c8\ub85c\uc6b4 \ub514\ub809\ud1a0\ub9ac \uad6c\uc870, \ub370\uc774\ud130 fetching \ubc29\uc2dd, DX\uac00 \uc88b\uc544\uc9c4 Nuxt 4.0\uac00 \ubc30\ud3ec\ub418\uc5c8\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://remix.run/blog/react-router-and-react-server-components\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://remix.run/blog/react-router-and-react-server-components</a><p data-notion-block-id=\\"232e548d-8a8e-8014-8207-c09950b19126\\">React Router\uc5d0\uc11c RSC \uc9c0\uc6d0\uc774 \ubca0\ud0c0\ub85c \uc2dc\uc791\ub418\uc5c8\ub2e4\ub294 \uc18c\uc2dd\uc740 \ub4dc\ub838\uc9c0\ub9cc, \uadf8 \ubbf8\ub798\ub294 \uc5b4\ub5bb\uac8c \ub420 \uac83\uc778\uc9c0\ub97c \uc18c\uac1c\ub418\uc9c0 \uc54a\uc544\uc11c, \uadf8 \ubbf8\ub798\ub97c \uc18c\uac1c\ud558\ub294  \uae00\uc785\ub2c8\ub2e4.</p><a href=\\"https://hyperfetch.bettertyped.com/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://hyperfetch.bettertyped.com/</a><p data-notion-block-id=\\"232e548d-8a8e-8086-a5de-fe5b0385d722\\">Tanstack Query\ucc98\ub7fc \uc11c\ubc84 \uc0c1\ud0dc\ub97c \uac00\uc838\uc624\ub294 \uc5ed\ud560\uc744 \ud558\uc9c0\ub9cc, \ud558\uc9c0\ub9cc \ub2e4\ub978 \uc811\uadfc \ubc29\uc2dd\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc9c4 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc778 Hyperfetch\uc785\ub2c8\ub2e4. \ub354 \ubcf5\uc7a1\ud558\uace0 \uc790\uc138\ud558\uac8c \uad00\ub9ac\ud558\ub294\ub370\uc5d0 \uc88b\uc740 \uc5ed\ud560\uc744 \ud560 \uac83\uc73c\ub85c \ubcf4\uc785\ub2c8\ub2e4.</p><a href=\\"https://github.com/colinhacks/zshy\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/colinhacks/zshy</a><p data-notion-block-id=\\"235e548d-8a8e-8013-8a53-e79baaa8429b\\">\ubc88\ub4e4\ub7ec \uc5c6\uc774 TypeScript \ucef4\ud30c\uc77c\ub7ec API\ub97c \uae30\ubc18\uc73c\ub85c \ube4c\ub4dc\ud574\uc8fc\ub294 \ube4c\ub4dc \ud234\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"239e548d-8a8e-8059-83ba-df566e725086\\" id=\\"239e548d-8a8e-8059-83ba-df566e725086\\">\ubc88\uc678: AI\ub294 \uc815\ub9d0 \uc0dd\uc0b0\uc131\uc744 \uac00\uc838\uc624\ub294\uac00</h2><a href=\\"https://metr.org/blog/2025-07-10-early-2025-ai-experienced-os-dev-study/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://metr.org/blog/2025-07-10-early-2025-ai-experienced-os-dev-study/</a><p data-notion-block-id=\\"235e548d-8a8e-8056-9f7a-f94db8151caf\\">\uc624\ud508\uc18c\uc2a4 \uac1c\ubc1c\uc790\uac00 \uacbd\ud5d8\ud55c AI\uc758 \uc0dd\uc0b0\uc131\uc740 \ub0ae\uc544\uc84c\ub2e4\ub294 \ud1b5\uacc4\uc785\ub2c8\ub2e4. AI\ub85c \uc778\ud55c \uc0dd\uc0b0\uc131 \ud5a5\uc0c1\uc774 \uac70\uc9d3\uc774 \uc544\ub2cc\uac00\ub294 \uc885\ud569\ud574\uc11c \uace0\ub824\ud574\ubd10\uc57c \ud55c\ub2e4\ub294 \uad50\ud6c8\uc744 \ub0a8\uae30\ub294 \uae00\uc785\ub2c8\ub2e4.</p>"}')}}]);